-- A post for the PostgreSQL copy of the InvoiceSystem sample. Settings: ContentTables=Post, OnlyTables=Post
-- The same table as Schemas/content.sql (and the SQL Server copy); the unique slug is the rule the server's numbering keeps.
CREATE TABLE IF NOT EXISTS "Post" (
    "PostId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Title" varchar(150) NOT NULL,
    "Slug" varchar(150) NOT NULL,
    "Body" text NOT NULL,
    "Status" varchar(12) NOT NULL DEFAULT 'draft',
    "PublishedOn" timestamp NULL,
    "CreatedOn" timestamp NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_Post_Slug" ON "Post" ("Slug");
